-- Catalogue élargi (docs/06 F18) : arbres et arbustes de jardin, fruitiers, herbes sauvages utiles et
-- mauvaises herbes. Catégorie « sauvages » et indicateur weed (« Mauvaise herbe »).
-- Conifères absents : aucun des 19 types de dessin ne les représente (CLAUDE.md fixe les 19 types).
alter table public.species drop constraint species_category_check;
alter table public.species add constraint species_category_check
  check (category in ('feuillage','succulentes','aromatiques','fleurs','arbres','retombantes','sauvages'));
alter table public.species add column weed boolean not null default false;

on conflict (id) do nothing;
